import{_ as d,a0 as l,w as r,s as p,ao as n,I as o,x as s,a1 as a,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"命令行快速提示：权限 | LCTT x X-CMD","titleTemplate":false,"description":"命令行快速提示：权限 | LCTT (201907) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"命令行快速提示：权限 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"命令行快速提示：权限 | LCTT (201907) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201907/20190708 Command line quick tips- Permissions","title":"命令行快速提示：权限","tag":"201907","desc":""},"relativePath":"201907/20190708 Command line quick tips- Permissions.md","filePath":"[post].md"}'),h={name:"201907/20190708 Command line quick tips- Permissions.md"};function c(g,e,u,k,m,b){const i=l("Link");return r(),p("div",null,[e[20]||(e[20]=n(`<h1 id="命令行快速提示-权限" tabindex="-1">命令行快速提示：权限 <a class="header-anchor" href="#命令行快速提示-权限" aria-label="Permalink to “命令行快速提示：权限”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2018/10/commandlinequicktips-816x345.jpg" alt=""></p><p>Fedora 与所有基于 Linux 的系统一样，它提供了一组强大的安全特性。其中一个基本特性是文件和文件夹上的<em>权限</em>。这些权限保护文件和文件夹免受未经授权的访问。本文将简要介绍这些权限，并向你展示如何使用它们共享对文件夹的访问。</p><h3 id="权限基础" tabindex="-1">权限基础 <a class="header-anchor" href="#权限基础" aria-label="Permalink to “权限基础”">​</a></h3><p>Fedora 本质上是一个多用户操作系统，它也有<em>组</em>，用户可以是其成员。但是，想象一下一个没有权限概念的多用户系统，不同的登录用户可以随意阅读彼此的内容。你可以想象到这对隐私或安全性并不是很好。</p><p>Fedora 上的任何文件或文件夹都分配了三组权限。第一组用于拥有文件或文件夹的<em>用户</em>，第二组用于拥有它的<em>组</em>，第三组用于其他人，即既不是该文件的用户也不是拥有该文件的组中的用户。有时这被称为<em>全世界</em>。</p><h3 id="权限意味着什么" tabindex="-1">权限意味着什么 <a class="header-anchor" href="#权限意味着什么" aria-label="Permalink to “权限意味着什么”">​</a></h3><p>每组权限都有三种形式：<em>读</em>、<em>写</em>和<em>执行</em>。其中每个都可以用首字母来代替，即 <code>r</code>、<code>w</code>、<code>x</code>。</p><h4 id="文件权限" tabindex="-1">文件权限 <a class="header-anchor" href="#文件权限" aria-label="Permalink to “文件权限”">​</a></h4><p>对于<em>文件</em>，权限的含义如下所示：</p><ul><li>读（<code>r</code>）：可以读取文件内容</li><li>写（<code>w</code>）：可以更改文件内容</li><li>执行（<code>x</code>）：可以执行文件 —— 这主要用于打算直接运行的程序或脚本</li></ul><p>当你对任何文件进行详细信息列表查看时，可以看到这三组权限。尝试查看系统上的 <code>/etc/services</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l /etc/services</span></span>
<span class="line"><span>-rw-r--r--. 1 root root 692241 Apr  9 03:47 /etc/services</span></span></code></pre></div><p>注意列表左侧的权限组。如上所述，这些表明三种用户的权限：拥有该文件的用户，拥有该文件的组以及其他人。用户所有者是 <code>root</code>，组所有者是 <code>root</code> 组。用户所有者具有对文件的读写权限，<code>root</code> 组中的任何人都只能读取该文件。最后，其他任何人也只能读取该文件。（最左边的 <code>-</code> 显示这是一个常规文件。）</p><p>顺便说一下，你通常会在许多（但不是所有）系统配置文件上发现这组权限，它们只由系统管理员而不是普通用户更改。通常，普通用户需要读取其内容。</p><h4 id="文件夹-目录-权限" tabindex="-1">文件夹（目录）权限 <a class="header-anchor" href="#文件夹-目录-权限" aria-label="Permalink to “文件夹（目录）权限”">​</a></h4><p>对于文件夹，权限的含义略有不同：</p><ul><li>读（<code>r</code>）：可以读取文件夹内容（例如 <code>ls</code> 命令）</li><li>写（<code>w</code>）：可以更改文件夹内容（可以在此文件夹中创建或删除文件）</li><li>执行（<code>x</code>）：可以搜索文件夹，但无法读取其内容。（这听起来可能很奇怪，但解释起来需要更复杂的文件系统细节，这超出了本文的范围，所以现在就这样吧。）</li></ul><p>看一下 <code>/etc/grub.d</code> 文件夹的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -ld /etc/grub.d</span></span>
<span class="line"><span>drwx------. 2 root root 4096 May 23 16:28 /etc/grub.d</span></span></code></pre></div><p>注意最左边的 <code>d</code>，它显示这是一个目录或文件夹。权限显示用户所有者（<code>root</code>）可以读取、更改和 <code>cd</code> 到此文件夹中。但是，没有其他人可以这样做 —— 无论他们是否是 <code>root</code> 组的成员。注意，你不能 <code>cd</code> 进入该文件夹。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd /etc/grub.d</span></span>
<span class="line"><span>bash: cd: /etc/grub.d: Permission denied</span></span></code></pre></div><p>注意你自己的主目录是如何设置的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -ld $HOME</span></span>
<span class="line"><span>drwx------. 221 paul paul 28672 Jul  3 14:03 /home/paul</span></span></code></pre></div><p>现在，注意除了作为所有者之外，没有人可以访问此文件夹中的任何内容。这是特意的！你不希望其他人能够在共享系统上读取你的私人内容。</p><h3 id="创建共享文件夹" tabindex="-1">创建共享文件夹 <a class="header-anchor" href="#创建共享文件夹" aria-label="Permalink to “创建共享文件夹”">​</a></h3><p>你可以利用此权限功能轻松创建一个文件夹以在组内共享。假设你有一个名为 <code>finance</code> 的小组，其中有几个成员需要共享文档。因为这些是用户文档，所以将它们存储在 <code>/home</code> 文件夹层次结构中是个好主意。</p>`,27)),o("p",null,[e[1]||(e[1]=s("首先，",-1)),a(i,{href:"https://fedoramagazine.org/howto-use-sudo/"},{default:t(()=>[...e[0]||(e[0]=[s("使用 sudo",-1)])]),_:1}),e[2]||(e[2]=s(" 创建一个共享文件夹，并将其设置为 ",-1)),e[3]||(e[3]=o("code",null,"finance",-1)),e[4]||(e[4]=s(" 组所有：",-1))]),e[21]||(e[21]=n(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mkdir -p /home/shared/finance</span></span>
<span class="line"><span>$ sudo chgrp finance /home/shared/finance</span></span></code></pre></div><p>默认情况下，新文件夹具有这些权限。注意任何人都可以读取或搜索它，即使他们无法创建或删除其中的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>drwxr-xr-x. 2 root root 4096 Jul  6 15:35 finance</span></span></code></pre></div><p>对于金融数据来说，这似乎不是一个好主意。接下来，使用 <code>chmod</code> 命令更改共享文件夹的模式（权限）。注意，使用 <code>g</code> 更改所属组的权限，使用 <code>o</code> 更改其他用户的权限。同样，<code>u</code> 会更改用户所有者的权限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chmod g+w,o-rx /home/shared/finance</span></span></code></pre></div><p>生成的权限看起来更好。现在，<code>finance</code> 组中的任何人（或用户所有者 <code>root</code>）都可以完全访问该文件夹及其内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>drwxrwx---. 2 root finance 4096 Jul  6 15:35 finance</span></span></code></pre></div><p>如果其他用户尝试访问共享文件夹，他们将无法执行此操作。太棒了！现在，我们的金融部门可以将文档放在一个共享的地方。</p><h3 id="其他说明" tabindex="-1">其他说明 <a class="header-anchor" href="#其他说明" aria-label="Permalink to “其他说明”">​</a></h3><p>还有其他方法可以操作这些权限。例如，你可能希望将此文件夹中的任何文件设置为 <code>finance</code> 组所拥有。这需要本文未涉及的其他设置，但请继续关注我们，以了解关于该主题的更多信息。</p><hr>`,11)),o("p",null,[e[6]||(e[6]=s("via: ",-1)),a(i,{href:"https://fedoramagazine.org/command-line-quick-tips-permissions/"},{default:t(()=>[...e[5]||(e[5]=[s("https://fedoramagazine.org/command-line-quick-tips-permissions/",-1)])]),_:1})]),o("p",null,[e[11]||(e[11]=s("作者：",-1)),a(i,{href:"https://fedoramagazine.org/author/pfrields/"},{default:t(()=>[...e[7]||(e[7]=[s("Paul W. Frields",-1)])]),_:1}),e[12]||(e[12]=s(" 选题：",-1)),a(i,{href:"https://github.com/lujun9972"},{default:t(()=>[...e[8]||(e[8]=[s("lujun9972",-1)])]),_:1}),e[13]||(e[13]=s(" 译者：",-1)),a(i,{href:"https://github.com/MjSeven"},{default:t(()=>[...e[9]||(e[9]=[s("MjSeven",-1)])]),_:1}),e[14]||(e[14]=s(" 校对：",-1)),a(i,{href:"https://github.com/wxy"},{default:t(()=>[...e[10]||(e[10]=[s("wxy",-1)])]),_:1})]),o("p",null,[e[17]||(e[17]=s("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[15]||(e[15]=[s("LCTT",-1)])]),_:1}),e[18]||(e[18]=s(" 原创编译，",-1)),a(i,{href:"https://linux.cn/"},{default:t(()=>[...e[16]||(e[16]=[s("Linux中国",-1)])]),_:1}),e[19]||(e[19]=s(" 荣誉推出",-1))])])}const T=d(h,[["render",c]]);export{C as __pageData,T as default};
